const { Vector3 } = BABYLON;
const { Assembly, v } = use('petrel/geometry');

const TAU = Math.PI * 2;
const rad = degrees => degrees * Math.PI / 180;
// Shared default directions, frozen so that no caller can change them for every other one.
const up = Object.freeze(v(0, 1, 0));
const down = Object.freeze(v(0, -1, 0));
const radial = (a, r, y, side = 0) => v(
  Math.sin(a) * r + Math.cos(a) * side, y, Math.cos(a) * r - Math.sin(a) * side,
);

function metricUV(points, normal, material) {
  const scale = material.metadata?.tile || 5;
  const ax = Math.abs(normal.x), ay = Math.abs(normal.y), az = Math.abs(normal.z);
  if (ay >= ax && ay >= az) return points.map(p => [p.x / scale, p.z / scale]);
  return points.map(p => [(ax > az ? p.z : p.x) / scale, p.y / scale]);
}

// The shared Petrel assembler batches these plates, extrusions and rails by finish.
class Fabrication extends Assembly {
  plate(material, points, outward, uv, normals) {
    this.face(material, points, outward, normals, uv || metricUV(points, outward, material));
  }

  join(material, lower, upper) {
    for (let i = 0; i < lower.length; i++) {
      const j = (i + 1) % lower.length;
      const points = [lower[i], lower[j], upper[j], upper[i]];
      const outward = Vector3.Cross(upper[i].subtract(lower[i]), lower[j].subtract(lower[i]));
      this.plate(material, points, outward);
    }
  }

  // Pad outlines run counterclockwise in the local X/Z drawing.
  slab(material, outline, bottom, top, topMaterial = material, topUV) {
    const low = outline.map(([x, z]) => v(x, bottom, z));
    const high = outline.map(([x, z]) => v(x, top, z));
    this.join(material, low, high);
    this.plate(material, low, down);
    this.plate(topMaterial, high, up, topUV);
  }

  box(material, x, y, z, width, height, depth) {
    const a = width / 2, b = depth / 2;
    this.slab(material, [[x-a,z-b],[x+a,z-b],[x+a,z+b],[x-a,z+b]], y-height/2, y+height/2);
  }

  // Local width follows the edge perpendicular to the supplied face direction.
  bar(material, a, b, width, height, hint = up) {
    const along = b.subtract(a).normalize();
    // A hint along the bar gives it no side: it takes an axis the bar is not along.
    const guide = Math.abs(Vector3.Dot(along, hint)) > .995 ? (Math.abs(along.x) > .9 ? v(0,0,1) : v(1,0,0)) : hint;
    const across = Vector3.Cross(guide, along);
    // Only a bar of no length is left without a side: every face would be dropped.
    if (across.lengthSquared() < 1e-12) throw new RangeError('A bar needs two ends apart.');
    const side = across.normalize().scale(width/2);
    const rise = Vector3.Cross(along, side).normalize().scale(height/2);
    const offsets = [side.negate().subtract(rise), side.subtract(rise), side.add(rise), rise.subtract(side)];
    const low = offsets.map(p => a.add(p)), high = offsets.map(p => b.add(p));
    for(let i=0;i<4;i++){
      const next=(i+1)%4;
      this.plate(material,[low[i],low[next],high[next],high[i]],offsets[i].add(offsets[next]));
    }
    this.plate(material, low, along.negate());
    this.plate(material, high, along);
  }

  girder(material, a, b, width, height, face = up) {
    const axis = b.subtract(a).normalize();
    const normal = face.subtract(axis.scale(Vector3.Dot(axis, face)));
    if (normal.lengthSquared() < 1e-12) throw new RangeError('A girder cannot face along its own axis.');
    normal.normalize();
    const lip = height * .17, offset = normal.scale((height-lip)/2);
    this.bar(material, a, b, width*.34, height-2*lip, normal);
    this.bar(material, a.add(offset), b.add(offset), width, lip, normal);
    this.bar(material, a.subtract(offset), b.subtract(offset), width, lip, normal);
  }

  tube(material, a, b, radius, endRadius = radius, sides = 10) {
    const axis = b.subtract(a).normalize();
    const u = Vector3.Cross(Math.abs(axis.y) > .95 ? v(1,0,0) : up, axis).normalize();
    const w = Vector3.Cross(axis, u);
    const low = [], high = [];
    for (let i=0; i<sides; i++) {
      const angle = TAU*i/sides;
      const normal = u.scale(Math.cos(angle)).addInPlace(w.scale(Math.sin(angle)));
      low.push(a.add(normal.scale(radius)));
      high.push(b.add(normal.scale(endRadius)));
    }
    this.sleeve(low, high, material, {smooth:true});
    this.plate(material, low, axis.negate());
    this.plate(material, high, axis);
  }

  // Closed radial sections travel from the inner edge over the roof to the outside.
  // A null band is an actual opening. Glass and service inserts occupy selected openings.
  revolve(rows, start = 0, end = TAU, segments = 96, sectionNormal) {
    const columns = Array.from({length:segments+1}, (_,i) => {
      const angle = start + (end-start)*i/segments;
      return {angle, points:rows.map(([r,y]) => radial(angle,r,y))};
    });
    for (let i=0; i<segments; i++) {
      const left = columns[i], right = columns[i+1], mid = (left.angle+right.angle)/2;
      for (let j=0; j+1<rows.length; j++) {
        const [r,y,m] = rows[j], [r2,y2] = rows[j+1];
        if (!m) continue;
        const dr = r2-r, dy = y2-y;
        const normal = a => radial(a,-dy,dr).normalize();
        const section = sectionNormal || normal;
        const points = [left.points[j],right.points[j],right.points[j+1],left.points[j+1]];
        const scale = m.metadata?.tile || 5, ring = (r+r2)/2;
        const height = (rr,yy) => Math.abs(dr) > Math.abs(dy) ? rr/scale : yy/scale;
        const corners = [[left.angle,r,y],[right.angle,r,y],[right.angle,r2,y2],[left.angle,r2,y2]];
        this.plate(m, points, normal(mid), corners.map(([a,rr,yy]) => [a*ring/scale,height(rr,yy)]), corners.map(([a,rr,yy]) => section(a,rr,yy)));
      }
    }
  }

  band(m, inside, outside, bottom, top, a=0, b=TAU, count=64) {
    this.revolve([[inside,bottom,m],[inside,top,m],[outside,top,m],[outside,bottom,m],[inside,bottom]], a,b,count);
  }

  // The yard's pipes are a few pixels thick at the nearest view: six sides draw them round.
  pipeArc(m, r, y, radius, a, b, sections = 20) {
    const row = [], sides = 6;
    for (let j=0; j<=sides; j++) {
      const cross = Math.PI - TAU*j/sides;
      row.push([r+radius*Math.cos(cross), y+radius*Math.sin(cross), m]);
    }
    this.revolve(row,a,b,sections,(angle,rr,yy)=>radial(angle,rr-r,yy-y).normalize());
  }
}
return { Fabrication, TAU, rad, radial, up, v };
